class FileProblemTests(ShopTestCase):
    def test_missing_catalog_is_exit_2_for_every_command(self):
        self.shop(catalog=None)
        for argv in (["stock"], ["low"], ["history", "AB-100"], ["receive", "2024-01-01", "AB-100", "1"],
                     ["ship", "2024-01-01", "AB-100", "1"], ["quote", "SO-1001"], ["fulfil", "SO-1001", "2024-03-10"],
                     ["invoice", "SO-1001"], ["report"]):
            self.assertRefused(self.run_cli(*argv), 2, "catalog.txt")

    def test_missing_folder(self):
        result = self.run_cli("--dir", os.path.join(self.dir, "nope"), "stock", dir=False)
        self.assertRefused(result, 2)

    def test_folder_is_a_file(self):
        self.shop()
        result = self.run_cli("--dir", os.path.join(self.dir, "catalog.txt"), "stock", dir=False)
        self.assertRefused(result, 2)

    def test_not_utf8(self):
        for name in ("catalog.txt", "movements.txt", "orders.txt"):
            self.shop()
            self.write(name, b"# caf\xe9\n")
            result = self.run_cli("report")
            self.assertRefused(result, 2, name)

    def test_utf16_is_not_utf8(self):
        self.shop()
        self.write("catalog.txt", "AB-100|x|1|0\n".encode("utf-16"))
        self.assertRefused(self.run_cli("stock"), 2)

    def test_bom_and_crlf_files(self):
        self.write("catalog.txt", b"\xef\xbb\xbfAB-100|Gnome|1|0\r\n")

